package com.hireflow.api.notification; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationRepository r; public NotificationController(NotificationRepository x){r=x;} @GetMapping public List<Notification> mine(@RequestHeader("X-User-Email")String e){return r.findByEmailOrderByCreatedAtDesc(e);} @PatchMapping("/{id}/read") public Notification read(@PathVariable Long id){Notification n=r.findById(id).orElseThrow();n.setReadFlag(true);return r.save(n);}}